import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.DJVIMu25.js";const p=JSON.parse('{"title":"Music Player","description":"","frontmatter":{"title":"Music Player"},"headers":[],"relativePath":"en/guides/music.md","filePath":"en/guides/music.md","lastUpdated":1786545590000}'),s={name:"en/guides/music.md"};function l(r,e,n,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="music-player" tabindex="-1">Music Player <a class="header-anchor" href="#music-player" aria-label="Permalink to &quot;Music Player&quot;">​</a></h1><p>JoyMart includes a built-in background music player that plays NBS (Note Block Studio) songs through Minecraft&#39;s native note-block sounds — no resource pack required.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li>Songs are loaded from <code>.nbs</code> files in the <code>plugins/JoyMart/music/</code> directory</li><li>The <code>NbsSong</code> parser extracts the tempo and per-tick notes</li><li>A per-player scheduled task advances one NBS tick at a time (paced by the song&#39;s tempo)</li><li>Each note is played through <code>Player#playSound</code> using Minecraft&#39;s built-in note-block sounds (e.g. <code>BLOCK_NOTE_BLOCK_HARP</code>, <code>BLOCK_NOTE_BLOCK_BASS</code>, etc.)</li><li>Each player has their own scheduled task and playback state, so different players can listen to different songs simultaneously</li></ul><h2 id="nbs-tempo-and-tick-scheduling" tabindex="-1">NBS tempo and tick scheduling <a class="header-anchor" href="#nbs-tempo-and-tick-scheduling" aria-label="Permalink to &quot;NBS tempo and tick scheduling&quot;">​</a></h2><ul><li>NBS tempo is stored as ticks-per-second × 100 (so <code>1000</code> means 10 tps)</li><li>The server runs at 20 ticks/second, so one NBS tick takes <code>2000 / tempo</code> server ticks</li><li>That ratio is rounded to the nearest whole tick and used as the <code>runTaskTimer</code> period</li><li>Tempos up to 2000 (20 tps) are exact; higher tempos play slightly slower (rounded up to 1 server tick per NBS tick)</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Because the server is fixed at 20 ticks/second, songs with a tempo above 2000 (i.e. 20 tps) cannot be reproduced exactly — actual playback will be slightly slower than the configured value.</p></div><h2 id="adding-songs" tabindex="-1">Adding songs <a class="header-anchor" href="#adding-songs" aria-label="Permalink to &quot;Adding songs&quot;">​</a></h2><ol><li>Obtain <code>.nbs</code> files (created with <a href="https://onlinesequencer.net/" target="_blank" rel="noreferrer">Open Note Block Studio</a> or similar tools)</li><li>Place them in the <code>plugins/JoyMart/music/</code> directory</li><li>Restart the server or run <code>/gba reload</code></li><li>Players can access the music player GUI from the JoyMart main menu</li></ol><h2 id="music-player-gui" tabindex="-1">Music Player GUI <a class="header-anchor" href="#music-player-gui" aria-label="Permalink to &quot;Music Player GUI&quot;">​</a></h2><ul><li>Accessed from the JoyMart main menu</li><li>Shows a list of loaded songs</li><li>Players can play, stop, and switch songs independently</li><li>Song names fall back to the file name (without extension) if the NBS file has no in-file title</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Each player&#39;s playback state is independent, so multiple players can listen to different tracks at the same time without interfering with each other.</p></div><h2 id="inspiration" tabindex="-1">Inspiration <a class="header-anchor" href="#inspiration" aria-label="Permalink to &quot;Inspiration&quot;">​</a></h2><p>The music player was inspired by <a href="https://www.spigotmc.org/resources/jukebox-music-plugin.40580/" target="_blank" rel="noreferrer">JukeBox - Music Plugin</a>. JoyMart&#39;s implementation is independently written from scratch — NBS parsing, per-player scheduling, and the GUI are all original code.</p><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./getting-started">Getting Started</a></li><li><a href="./games">Game Modes</a></li></ul>',16)])])}const m=a(s,[["render",l]]);export{p as __pageData,m as default};
